// Keep the filesystem/privilege boundary mockable without executing privileged
// commands in regression tests.
export const removalIO = {
  lstat: filesystem.lstat,
  rm: filesystem.rm,
  unlink: filesystem.unlink,
  runElevated,
};

type RemovalSnapshot =
  | { readonly exists: false }
  | {
      readonly exists: true;
      readonly device: bigint;
      readonly inode: bigint;
      readonly birthtime: bigint;
      readonly kind: bigint;
      readonly isLink: boolean;
    };

// Some adapters validate and remove through separate public helper calls.
// Retain their baseline for the lifetime of the runtime context, just as a
// createRemovePathOperation retains its baseline in its operation closure.
const validatedRemovals = new WeakMap<RuntimeContext, Map<string, RemovalSnapshot>>();

function removalKey(target: string, context: RuntimeContext): string {
  return context.platform === "windows"
    ? win32.normalize(target).toLowerCase()
    : normalize(target);
}

async function removalSnapshot(target: string): Promise<RemovalSnapshot> {
  try {
    // Do not follow final links, including dangling links and junctions.
    const stat = await removalIO.lstat(target, { bigint: true });
    return {
      exists: true,
      device: stat.dev,
      inode: stat.ino,
      birthtime: stat.birthtimeNs,
      kind: stat.mode & 0o170000n,
      isLink: stat.isSymbolicLink(),
    };
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") {
      return { exists: false };
    }
    throw error;
  }
}

function sameRemovalTarget(
  left: RemovalSnapshot,
  right: RemovalSnapshot,
): boolean {
  if (!left.exists || !right.exists) return left.exists === right.exists;
  return (
    left.device === right.device &&
    left.inode === right.inode &&
    left.birthtime === right.birthtime &&
    left.kind === right.kind &&
    left.isLink === right.isLink
  );
}

async function validatedRemovalSnapshot(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
): Promise<RemovalSnapshot> {
  const before = await removalSnapshot(target);
  await assertSafeExistingTarget(target, allowedParents, context);
  const after = await removalSnapshot(target);
  if (!sameRemovalTarget(before, after)) {
    throw new Error(`Cleanup target changed during safety validation: '${target}'.`);
  }
  return after;
}

export async function validateRemovePathTarget(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
): Promise<void> {
  const snapshot = await validatedRemovalSnapshot(target, allowedParents, context);
  let targets = validatedRemovals.get(context);
  if (targets === undefined) {
    targets = new Map();
    validatedRemovals.set(context, targets);
  }
  targets.set(removalKey(target, context), snapshot);
}

export async function removePathTarget(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
): Promise<OperationResult> {
  try {
    const validated = validatedRemovals.get(context)?.get(removalKey(target, context))
      ?? await validatedRemovalSnapshot(target, allowedParents, context);
    return await removeValidatedPathTarget(target, allowedParents, context, validated);
  } catch (error) {
    return {
      status: "failed",
      detail: error instanceof Error ? error.message : String(error),
    };
  }
}

async function removeValidatedPathTarget(
  target: string,
  allowedParents: readonly string[],
  context: RuntimeContext,
  validated: RemovalSnapshot,
): Promise<OperationResult> {
  const changed = (): OperationResult => ({
    status: "failed",
    detail: `Cleanup target changed after safety validation: '${target}'.`,
  });
  const remains = (): OperationResult => ({
    status: "failed",
    detail: `Cleanup target remains after removal: '${target}'.`,
  });
  try {
    // Recheck ancestors as well as final-target identity. These observations
    // detect boundary-visible changes; they do not make OS deletion atomic.
    const immediate = await validatedRemovalSnapshot(target, allowedParents, context);
    if (!immediate.exists) return { status: "not-found" };
    if (!sameRemovalTarget(validated, immediate)) return changed();

    let nativeFailed = false;
    let nativeDetail = "";
    try {
      if (immediate.isLink) {
        await removalIO.unlink(target);
      } else {
        await removalIO.rm(target, {
          recursive: true,
          force: true,
          maxRetries: 3,
          retryDelay: 100,
        });
      }
    } catch (error) {
      nativeFailed = true;
      nativeDetail = error instanceof Error ? error.message : String(error);
    }

    if (!nativeFailed) {
      // A successful return is not proof of removal. Never escalate a nominal
      // success that left a target (possibly a replacement) behind.
      return (await removalSnapshot(target)).exists ? remains() : { status: "removed" };
    }

    const retry = await validatedRemovalSnapshot(target, allowedParents, context);
    if (!retry.exists) return { status: "removed" };
    if (!sameRemovalTarget(validated, retry)) return changed();
    if (context.platform === "windows") {
      return { status: "failed", detail: nativeDetail };
    }

    const result = await removalIO.runElevated(
      context,
      "/bin/rm",
      [retry.isLink ? "-f" : "-rf", "--", target],
      { silent: true, timeoutMs: 10 * 60_000 },
    );
    if (result.exitCode !== 0) {
      return {
        status: "failed",
        detail: result.stderr.trim() || nativeDetail,
      };
    }
    return (await removalSnapshot(target)).exists ? remains() : { status: "removed" };
  } catch (error) {
    return {
      status: "failed",
      detail: error instanceof Error ? error.message : String(error),
    };
  }
}

