test("removal retains validated identity and ordered best-effort results", async () => {
  const fs = (await import("node:fs")).promises;
  const root = await mkdtemp(join(tmpdir(), "maximize-space-identity-"));
  try {
    const context = { ...contextFor("linux"), temp: join(root, "runner-temp") };
    for (const kind of ["directory", "directory-to-link", "link-to-directory", "absent"] as const) {
      const target = join(root, kind);
      const original = `${target}-original`;
      const destination = `${target}-destination`;
      await mkdir(destination);
      await writeFile(join(destination, "sentinel"), "preserve");
      if (kind === "link-to-directory") {
        await symlink(destination, target, "junction");
      } else if (kind !== "absent") {
        await mkdir(target);
        await writeFile(join(target, "original"), "original");
      }
      const operation = createRemovePathOperation({
        id: kind,
        component: "vcpkg",
        description: kind,
        target,
        allowedParents: [root],
        context,
      });
      assert.ok(operation.validate);
      await operation.validate();
      if (kind !== "absent") await fs.rename(target, original);
      if (kind === "directory-to-link") {
        await symlink(destination, target, "junction");
      } else {
        await mkdir(target);
        await writeFile(join(target, "replacement"), "replacement");
      }
      const result = await operation.run();
      assert.equal(result.status, "failed");
      assert.match(result.detail ?? "", /changed/);
      assert.equal(await readFile(join(destination, "sentinel"), "utf8"), "preserve");
      assert.equal((await fs.lstat(target)).isSymbolicLink(), kind === "directory-to-link");
      if (kind !== "absent") assert.ok(await fs.lstat(original));
    }

    const replaced = join(root, "ordered-replaced");
    const ordinary = join(root, "ordered-ordinary");
    await mkdir(replaced);
    await writeFile(ordinary, "remove");
    const operation = (target: string) => createRemovePathOperation({
      id: target,
      component: "vcpkg",
      description: target,
      target,
      allowedParents: [root],
      context,
    });
    const mutation = createFunctionOperation({
      id: "replace-after-validation",
      component: "vcpkg",
      description: "replace disposable fixture",
      phase: "package",
      run: async () => {
        await fs.rename(replaced, `${replaced}-original`);
        await mkdir(replaced);
        return { status: "removed" };
      },
    });
    const results = await executeOperations([mutation, operation(replaced), operation(ordinary)]);
    assert.deepEqual(results.map(({ status }) => status), ["removed", "failed", "removed"]);
    assert.equal(results.filter(({ status }) => status === "failed").length, 1);
    assert.ok(await fs.lstat(replaced));
    await assert.rejects(fs.lstat(ordinary), { code: "ENOENT" });
  } finally {
    await fs.rm(root, { recursive: true, force: true });
  }
});

