  const { validateRemovePathTarget, removePathTarget } = await import("../src/operations.js");
  const root = await mkdtemp(join(tmpdir(), "maximize-space-helper-identity-"));
  try {
    const context = { ...contextFor("linux"), temp: join(root, "runner-temp") };
    const replaced = join(root, "replaced");
    const ordinary = join(root, "ordinary");
    await mkdir(replaced);
    await writeFile(join(replaced, "sentinel"), "original");
    await writeFile(ordinary, "remove");
    const operation = (target: string) => createFunctionOperation({
      id: target,
      component: "vcpkg",
      description: target,
      phase: "filesystem",
      validate: async () => await validateRemovePathTarget(target, [root], context),
      run: async () => await removePathTarget(target, [root], context),
    });
    const mutation = createFunctionOperation({
      id: "replace-helper-target",
      component: "vcpkg",
      description: "replace disposable helper fixture",
      phase: "package",
      run: async () => {
