        await mkdir(replaced);
        await writeFile(join(replaced, "sentinel"), "replacement");
        return { status: "removed" };
      },
    });
    const results = await executeOperations([mutation, operation(replaced), operation(ordinary)]);
    assert.deepEqual(results.map(({ status }) => status), ["removed", "failed", "removed"]);
    assert.match(results[1]?.detail ?? "", /changed after safety validation/);
    assert.equal(await readFile(join(replaced, "sentinel"), "utf8"), "replacement");
    assert.equal(await readFile(join(`${replaced}-original`, "sentinel"), "utf8"), "original");
    await assert.rejects(fs.lstat(ordinary), { code: "ENOENT" });
  } finally {
    await fs.rm(root, { recursive: true, force: true });
  }
});

test("removal checks outcomes and guards every privileged retry", async (t) => {
  const fs = (await import("node:fs")).promises;
  const { removalIO, removePathTarget } = await import("../src/operations.js");
  const root = await mkdtemp(join(tmpdir(), "maximize-space-retry-"));
  const nativeRm = fs.rm.bind(fs);
  const nativeLstat = fs.lstat.bind(fs);
  const nativeUnlink = fs.unlink.bind(fs);
  type Mode = "ordinary" | "no-op" | "partial" | "replacement" | "gone" | "denied" | "link";
  let mode: Mode = "ordinary";
  let elevatedCalls = 0;
  let nativeCalls = 0;
  let elevatedExit = 0;
  let elevatedDeletes = true;
  let expectedLink = false;
  let observationFails = false;
  let replaceOnObservation = 0;
  let observations = 0;
  t.mock.method(removalIO, "lstat", async (...args: Parameters<typeof removalIO.lstat>) => {
    observations += 1;
    const path = String(args[0]);
    if (observationFails) throw new Error("inspection denied");
    if (observations === replaceOnObservation) {
      await fs.rename(path, `${path}-original`);
      await fs.mkdir(path);
    }
    return await nativeLstat(...args);
  });
  t.mock.method(removalIO, "rm", async (path: string) => {
    nativeCalls += 1;
    if (mode === "ordinary") return await nativeRm(path, { recursive: true, force: true });
    if (mode === "no-op") return;
    if (mode === "partial") await nativeUnlink(join(path, "child"));
    if (mode === "replacement") {
      await fs.rename(path, `${path}-original`);
      await fs.mkdir(path);
    }
    if (mode === "gone") await nativeRm(path, { recursive: true, force: true });
    throw new Error("native denied");
  });
  t.mock.method(removalIO, "unlink", async () => {
    nativeCalls += 1;
    throw new Error("native denied");
  });
  t.mock.method(removalIO, "runElevated", async (_context, executable, args, options) => {
    elevatedCalls += 1;
    assert.equal(executable, "/bin/rm");
    assert.equal(args[0], expectedLink ? "-f" : "-rf");
    assert.equal(args[1], "--");
    assert.equal(options?.silent, true);
    assert.equal(options?.timeoutMs, 10 * 60_000);
    const path = args[2];
    assert.ok(path);
    assert.equal(path.startsWith(root), true);
    if (elevatedExit === 0 && elevatedDeletes) {
      if (expectedLink) await nativeUnlink(path);
      else await nativeRm(path, { recursive: true, force: true });
    }
    return { exitCode: elevatedExit, stdout: "", stderr: elevatedExit ? "privileged denied" : "" };
  });
  try {
    const cases: readonly {
      mode: Mode;
      exit?: number;
      deletes?: boolean;
      expected: string;
      retries: number;
    }[] = [
      { mode: "ordinary", expected: "removed", retries: 0 },
      { mode: "no-op", expected: "failed", retries: 0 },
      { mode: "partial", expected: "removed", retries: 1 },
      { mode: "replacement", expected: "failed", retries: 0 },
      { mode: "gone", expected: "removed", retries: 0 },
      { mode: "denied", expected: "removed", retries: 1 },
      { mode: "denied", exit: 1, expected: "failed", retries: 1 },
      { mode: "denied", deletes: false, expected: "failed", retries: 1 },
      { mode: "link", expected: "removed", retries: 1 },
    ];
    for (const [index, item] of cases.entries()) {
      mode = item.mode;
      elevatedExit = item.exit ?? 0;
      elevatedDeletes = item.deletes ?? true;
      expectedLink = mode === "link";
      elevatedCalls = 0;
      const target = join(root, `target-${index}`);
      const destination = `${target}-destination`;
      if (expectedLink) {
        await writeFile(destination, "preserve");
        await symlink(destination, target);
      } else {
        await mkdir(target);
        await writeFile(join(target, "child"), "child");
      }
      const context = { ...contextFor("linux"), temp: join(root, "runner-temp") };
      const result = await removePathTarget(target, [root], context);
      assert.equal(result.status, item.expected, `${index}: ${mode}`);
      assert.equal(elevatedCalls, item.retries, `${index}: ${mode}`);
      if (item.exit) assert.match(result.detail ?? "", /privileged denied/);
      if (mode === "no-op" || item.deletes === false) assert.match(result.detail ?? "", /remains/);
      if (mode === "replacement") {
        assert.match(result.detail ?? "", /changed/);
        assert.ok(await nativeLstat(target));
        assert.equal(await readFile(join(`${target}-original`, "child"), "utf8"), "child");
      }
      if (expectedLink) assert.equal(await readFile(destination, "utf8"), "preserve");
    }

    await t.test("Windows returns the native removal error without escalation", {
      skip: process.platform !== "win32",
    }, async () => {
      const target = join(root, "windows-native-failure");
      await mkdir(target);
      mode = "denied";
      nativeCalls = 0;
      elevatedCalls = 0;
      const result = await removePathTarget(target, [root], {
        ...contextFor("windows"), temp: join(root, "runner-temp"),
      });
      assert.equal(nativeCalls, 1);
      assert.deepEqual(result, { status: "failed", detail: "native denied" });
      assert.equal(elevatedCalls, 0);
      assert.ok(await nativeLstat(target));
    });

    for (const boundary of [2, 4]) {
      const target = join(root, `boundary-${boundary}`);
      await mkdir(target);
      observations = 0;
      replaceOnObservation = boundary;
      nativeCalls = 0;
      elevatedCalls = 0;
      const result = await removePathTarget(target, [root], {
        ...contextFor("linux"), temp: join(root, "runner-temp"),
      });
      assert.equal(result.status, "failed");
      assert.match(result.detail ?? "", /changed/);
      assert.equal(nativeCalls, 0);
      assert.equal(elevatedCalls, 0);
      assert.ok(await nativeLstat(target));
    }
    replaceOnObservation = 0;
    observationFails = true;
    nativeCalls = 0;
    elevatedCalls = 0;
    const result = await removePathTarget(join(root, "unobservable"), [root], contextFor("linux"));
    assert.equal(result.status, "failed");
    assert.match(result.detail ?? "", /inspection denied/);
    assert.equal(nativeCalls, 0);
    assert.equal(elevatedCalls, 0);
  } finally {
    t.mock.restoreAll();
    await nativeRm(root, { recursive: true, force: true });
  }
});

